<script setup>
import { computed, ref, watch } from 'vue'
import { useChargingCarbon } from '../composables/useChargingCarbon.js'
import { CARBON_SOURCES, CARBON_INPUT_DEFAULTS, ELECTRICITY_CO2_FACTORS, DEFAULT_GASOLINE_CO2_PER_LITRE, estimateChargingCarbon, createCarbonRecord, restoreCarbonRecords } from '../utils/chargingCarbon.js'
import { downloadPlanningCsv } from '../utils/plannerPss.js'
const { settings,estimate } = useChargingCarbon()
const records = ref([]), notice = ref('')
try { records.value = restoreCarbonRecords(JSON.parse(localStorage.getItem('weidu-carbon-records-v1') || '[]')) } catch { /* No saved scenarios. */ }
watch(records,value => { try { localStorage.setItem('weidu-carbon-records-v1',JSON.stringify(value)) } catch { notice.value='估算已完成，本机存储不可用，记录仅在当前页面保留。' } },{deep:true})
const result = computed(() => estimate.value.valid ? estimate.value : null)
const rows = computed(() => records.value.map(row => ({...row,result:estimateChargingCarbon(row.input)})))
const total = computed(() => rows.value.reduce((sum,row) => sum+row.result.avoidedCO2Kg,0))
const sensitivity = computed(() => [.8,1,1.2].map(multiplier => ({ consumption:settings.evKwhPer100Km*multiplier,
  result:estimateChargingCarbon({...settings,evKwhPer100Km:settings.evKwhPer100Km*multiplier}) })))
const barMax = computed(() => Math.max(1,result.value?.gasolineCO2Kg || 0,result.value?.electricityCO2Kg || 0))
const fmt = (value,digits=2) => value == null ? '—' : value.toFixed(digits)
const signed = value => value == null ? '—' : (value>0?'+':'')+value.toFixed(2)
const vehicleFields = [{key:'evKwhPer100Km',label:'行驶电耗（电池侧）kWh/100 km',step:.1,min:.1},{key:'gasolineLitresPer100Km',label:'对照汽油车油耗 L/100 km',step:.1,min:.1},{key:'chargingEfficiency',label:'充电效率（0～1）',step:.01,min:.01,max:1},{key:'gasolineKgCO2PerLitre',label:'汽油燃烧系数 kg CO₂/L',step:.0001,min:.0001}]
function record() {
  const entry=createCarbonRecord(settings)
  if (!entry) return
  records.value=[entry,...records.value].slice(0,100)
  notice.value='已保存本次情景估算，参数随记录固定；最多保留 100 条。'
}
function exportRows() {
  const entries=rows.value.length ? rows.value : result.value ? [{createdAt:new Date().toISOString(),input:{...settings},result:result.value}] : []
  downloadPlanningCsv('魏都区-单次充电碳排放估算.csv',['估算时刻','方法版本','电量方式','计量侧电量kWh','电池补电kWh','同等里程km','汽油车CO2kg','充电电力CO2kg','净减排CO2kg','减排比例%','电力因子kgCO2/kWh','因子区域年份','因子来源','电池侧电耗kWh/100km','对照油耗L/100km','充电效率','汽油系数kgCO2/L','口径'],
    entries.map(row => [row.createdAt,row.result.methodVersion,row.input.mode,row.result.gridKwh,row.result.batteryKwh,row.result.distanceKm,row.result.gasolineCO2Kg,row.result.electricityCO2Kg,row.result.avoidedCO2Kg,row.result.reductionPercent,row.result.factor.value,row.result.factor.name,row.result.factor.source || '用户情景假设',row.input.evKwhPer100Km,row.input.gasolineLitresPer100Km,row.input.chargingEfficiency,row.input.gasolineKgCO2PerLitre,'使用阶段CO2情景；非充电订单或核证减排量']))
}
</script>
<template>
  <section class="pss-workbench pss-carbon" aria-label="双碳与单次充电减排评估">
    <div class="pss-intro"><div><span class="pss-eyebrow">CARBON IMPACT PER CHARGE</span><h2>每一次充电，预计少排多少 CO₂？</h2><p>比较相同出行里程的汽油燃烧与充电电力排放，让充电设施规划连接到绿色交通。</p></div><a class="pss-policy-link" :href="CARBON_SOURCES.policy" target="_blank" rel="noopener noreferrer">“十五五”碳达峰行动依据 ↗</a></div>
    <div class="pss-carbon-hero" :class="{'is-increase':result?.verdict==='increase'}"><div><span>{{ result?.verdict==='increase' ? '本次情景预计增加排放' : result?.verdict==='neutral' ? '本次情景净排放差为零' : '本次充电预计减少排放' }}</span><strong data-testid="carbon-saving">{{ fmt(result ? Math.abs(result.avoidedCO2Kg) : null) }} <small>kg CO₂ / 次</small></strong><p>相同里程对照 · {{ result?.factor.name || '待选择电力因子' }} · 使用阶段 CO₂</p></div><div class="pss-carbon-hero-detail"><span>对照排放变化</span><b>{{ result ? signed(result.reductionPercent) : '—' }}%</b><p>正值为减排，负值为增排</p></div></div>
    <p v-if="!estimate.valid" class="pss-alert" role="alert">{{ estimate.errors.join('；') }}</p>
    <div class="pss-kpis"><article><span>对应行驶里程</span><strong>{{ fmt(result?.distanceKm,1) }}<small> km</small></strong><p>按电池侧电耗估算</p></article><article><span>同里程汽油车排放</span><strong>{{ fmt(result?.gasolineCO2Kg) }}<small> kg CO₂</small></strong><p>汽油 {{ fmt(result?.gasolineLitres) }} L × 燃烧系数</p></article><article><span>充电电力间接排放</span><strong>{{ fmt(result?.electricityCO2Kg) }}<small> kg CO₂</small></strong><p>计量侧 {{ fmt(result?.gridKwh) }} kWh × 电力因子</p></article><article><span>电池实际补入电量</span><strong>{{ fmt(result?.batteryKwh) }}<small> kWh</small></strong><p>已区分充电损耗与电量口径</p></article></div>
    <div class="pss-columns"><div class="pss-main-column">
      <section class="pss-card"><div class="pss-card-heading"><h3>本次充电</h3><button @click="Object.assign(settings,CARBON_INPUT_DEFAULTS)">恢复示例参数</button></div><div class="pss-carbon-mode" role="group" aria-label="充电量输入方式"><button :class="{active:settings.mode==='energy'}" :aria-pressed="settings.mode==='energy'" @click="settings.mode='energy'">直接输入充电量</button><button :class="{active:settings.mode==='soc'}" :aria-pressed="settings.mode==='soc'" @click="settings.mode='soc'">按电量百分比估算</button></div><div v-if="settings.mode==='energy'" class="pss-input-grid"><label class="pss-field">本次充电量 kWh<input v-model.number="settings.chargeKwh" type="number" min="0" step=".1" aria-label="本次充电量 kWh" /></label><label class="pss-field">电量口径<select v-model="settings.energyBasis" aria-label="电量口径"><option value="grid">充电器输入计量侧（含充电损耗）</option><option value="battery">电池实际补入电量</option></select></label></div><div v-else class="pss-input-grid"><label class="pss-field">可用电池容量 kWh<input v-model.number="settings.batteryCapacityKwh" type="number" min=".1" step=".1" /></label><label class="pss-field">起始电量 %<input v-model.number="settings.startSoc" type="number" min="0" max="100" step="1" /></label><label class="pss-field">目标电量 %<input v-model.number="settings.targetSoc" type="number" min="0" max="100" step="1" /></label></div><p class="pss-note">默认数值是示例车辆与充电情景，可用充电器输入侧电表读数或电池容量、电量变化替换。结算账单若计在充电器输出侧，请按实际计量口径换算，不能直接当输入电量。</p><div v-if="result" class="pss-carbon-bars"><div><span>同等里程汽油车 <b>{{ fmt(result.gasolineCO2Kg) }} kg</b></span><i :style="{width:result.gasolineCO2Kg/barMax*100+'%',background:'#8a98af'}"></i></div><div><span>充电对应电力 <b>{{ fmt(result.electricityCO2Kg) }} kg</b></span><i :style="{width:result.electricityCO2Kg/barMax*100+'%',background:'#1da77d'}"></i></div></div><div class="pss-batch"><button class="pss-primary" :disabled="!result" @click="record">记录本次估算</button><button :disabled="!result && !rows.length" @click="exportRows">导出估算与参数</button></div><p v-if="notice" class="pss-note" role="status">{{ notice }}</p></section>
      <section class="pss-card"><h3>车辆电耗变化时，结果会怎样？</h3><div class="pss-table-wrap"><table class="pss-table"><thead><tr><th>电池侧电耗</th><th>相同补电对应里程</th><th>单次净减排</th></tr></thead><tbody><tr v-for="(row,index) in sensitivity" :key="index"><td>{{ fmt(row.consumption,1) }} kWh/100 km</td><td>{{ fmt(row.result.valid ? row.result.distanceKm : null,1) }} km</td><td>{{ signed(row.result.valid ? row.result.avoidedCO2Kg : null) }} kg CO₂</td></tr></tbody></table></div><p class="pss-note">仅对当前车辆电耗作 ±20% 敏感性试算，不是统计置信区间。天气、空调、路况和驾驶习惯可能改变实际电耗。</p></section>
      <section class="pss-card"><div class="pss-card-heading"><h3>逐次估算记录</h3><span class="pss-note">{{ rows.length }} 次 · 净减排合计 {{ signed(total) }} kg</span></div><div v-if="rows.length" class="pss-table-wrap"><table class="pss-table"><thead><tr><th>估算时间</th><th>输入侧电量</th><th>电力因子</th><th>净减排</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ new Date(row.createdAt).toLocaleString('zh-CN') }}</td><td>{{ fmt(row.result.gridKwh) }} kWh</td><td>{{ row.result.factor.name }}</td><td>{{ signed(row.result.avoidedCO2Kg) }} kg</td><td><button :aria-label="'删除估算记录 '+row.id" @click="records=records.filter(item=>item.id!==row.id)">删除</button></td></tr></tbody></table></div><p v-else class="pss-empty">填写本次充电数据后，可逐次保存估算并汇总。</p><p class="pss-note">记录保存在本机浏览器，保存当次参数；修改当前车辆或因子不会重算旧记录。这是情景台账，不代表真实充电订单或核证减排量。</p></section>
    </div><aside class="pss-side-column">
      <section class="pss-card"><h3>电力排放因子</h3><label class="pss-field">地区与数据年份<select v-model="settings.factorId" aria-label="电力因子地区与年份"><option v-for="factor in ELECTRICITY_CO2_FACTORS" :key="factor.id" :value="factor.id">{{ factor.name }} · {{ factor.value }}</option><option value="custom">自定义情景因子</option></select></label><label v-if="settings.factorId==='custom'" class="pss-field">自定义 kg CO₂/kWh<input v-model.number="settings.customGridFactor" type="number" min="0" step=".0001" aria-label="自定义电力因子" /></label><p class="pss-note">当前 {{ result?.factor.value ?? '—' }} kg CO₂/kWh。官方选项来自生态环境部公布的 2023 年因子，发布于 2025 年底；已核对至 2026-10-16，属于历史年度平均，不是实时或未来预测因子。</p><a class="pss-source-link" :href="CARBON_SOURCES.electricity" target="_blank" rel="noopener noreferrer">官方电力排放因子表 ↗</a><p v-if="settings.factorId==='custom'" class="pss-note">自定义值作为情景假设；本页不自动认定绿电、光伏或碳抵消可按零排放核算。</p></section>
      <section class="pss-card"><h3>车辆与对照参数</h3><label v-for="field in vehicleFields" :key="field.key" class="pss-field">{{ field.label }}<input v-model.number="settings[field.key]" type="number" :min="field.min" :max="field.max" :step="field.step" :aria-label="field.label" /></label><p class="pss-note">示例：15 kWh/100 km、7.5 L/100 km、效率 0.90，均为可改假设。{{ Math.abs(settings.gasolineKgCO2PerLitre-DEFAULT_GASOLINE_CO2_PER_LITRE)<1e-9 ? '汽油系数由燃烧缺省参数与参考密度换算。' : '汽油系数已改为自定义情景值。' }}</p><a class="pss-source-link" :href="CARBON_SOURCES.gasoline" target="_blank" rel="noopener noreferrer">燃料参数依据（附录八）↗</a></section>
      <details class="pss-card pss-method" open><summary>计算过程与双碳口径</summary><p>① 输入电量 × 充电效率 = 电池补电。</p><p>② 电池补电 ÷ 电池侧百公里电耗 × 100 = 对应里程。</p><p>③ 对应里程 ÷ 100 × 油耗 × 汽油系数 = 对照排放。</p><p>④ 输入电量 × 电力因子 = 充电间接排放。</p><p>⑤ 净减排 = 对照排放 − 充电间接排放，保留负值。</p><p>汽油默认换算：44.8 GJ/t × 0.0189 tC/GJ × 0.98 × 44/12 × 参考密度 0.73 kg/L ≈ 2.2211 kg CO₂/L。参考密度属于本工具假设，实际油品可调整换算后的系数。</p><p>仅比较使用阶段 CO₂，不含整车与电池制造、燃油上游开采炼制、充电设施建设及 CH₄/N₂O，不称为全生命周期减排。减排归因假设同等里程原本由所设汽油车承担。</p><p v-if="result?.breakEvenGridFactor != null">当前收支平衡电力因子约 {{ fmt(result.breakEvenGridFactor,4) }} kg CO₂/kWh；高于此值时本情景将显示增排。</p><a class="pss-source-link" :href="CARBON_SOURCES.explanation" target="_blank" rel="noopener noreferrer">电力间接排放与碳足迹因子的区别 ↗</a></details>
    </aside></div>
  </section>
</template>
